#include <zephyr/ztest.h>
#include <zephyr/cbprintf.h>
#include <zephyr/cbprintf_package.h>
#include <string.h>
#include <stdio.h> // For snprintf

#define TEST_BUF_SIZE 256

static char print_buf[TEST_BUF_SIZE];
static char compare_buf[TEST_BUF_SIZE];
static uint8_t package_buf[TEST_BUF_SIZE];

/*
 * Helper function to package and then print a string,
 * then compare it with an expected string.
 */
static void test_package_and_compare(const char *fmt, const char *expected_str, ...)
{
    va_list ap;
    int len;

    // Package the arguments
    va_start(ap, expected_str);
    len = cbprintf_package_string_create_va(package_buf, sizeof(package_buf), fmt, ap);
    va_end(ap);

    zassert_true(len > 0 && len <= sizeof(package_buf), "Packaging failed or buffer too small");

    // Unpack and print the string
    len = cbprintf_package_print_string(package_buf, print_buf, sizeof(print_buf));
    zassert_true(len > 0 && len <= sizeof(print_buf), "Unpacking failed or buffer too small");

    // Compare with the expected string
    zassert_equal(strcmp(print_buf, expected_str), 0,
                  "Unpacked string '%s' does not match expected '%s'", print_buf, expected_str);
}

/*
 * Test cases for cbprintf_package_fsc
 */
static void test_cbprintf_fsc_package(void)
{
    // Test with various format specifiers and arguments
    test_package_and_compare("Hello, %s!", "Hello, World!", "World");
    test_package_and_compare("Number: %d", "Number: 123", 123);
    test_package_and_compare("Hex: %x", "Hex: 7b", 0x7b);
    test_package_and_compare("Pointer: %p", "Pointer: 0x12345678", (void *)0x12345678);
    test_package_and_compare("Float: %f", "Float: 3.140000", 3.14f);
    test_package_and_compare("Double: %lf", "Double: 2.718280", 2.71828);
    test_package_and_compare("Char: %c", "Char: A", 'A');
    test_package_and_compare("Long: %ld", "Long: 1234567890", 1234567890L);
    test_package_and_compare("Long Long: %lld", "Long Long: 9876543210987654321", 9876543210987654321LL);
    test_package_and_compare("Mixed: %s %d %x", "Mixed: test 10 ff", "test", 10, 0xff);

    // Test with an empty string
    test_package_and_compare("Empty: '%s'", "Empty: ''", "");

    // Test with a long string (ensure buffer is sufficient)
    char long_str[90]; // Make it slightly shorter than TEST_BUF_SIZE to leave room for format
    memset(long_str, 'A', sizeof(long_str) - 1);
    long_str[sizeof(long_str) - 1] = '\0';
    snprintf(compare_buf, sizeof(compare_buf), "Long string: %s", long_str);
    test_package_and_compare("Long string: %s", compare_buf, long_str);
}

/*
 * Test cases for cbprintf_package_must_runtime
 */
static void test_cbprintf_must_runtime_package(void)
{
    // This test typically checks if packaging works at runtime for non-FSC strings.
    // For simplicity, we'll ensure a basic runtime package works.
    test_package_and_compare("Runtime %s %d", "Runtime test 42", "test", 42);
}

/*
 * Test cases for cbprintf_package
 */
static void test_cbprintf_package(void)
{
    // The original error log showed "tes" as output when expecting something like "test".
    // This suggests a potential truncation or off-by-one error when handling short strings.
    // This test case specifically targets that scenario.
    test_package_and_compare("String: %s", "String: test", "test");

    // Test with a string that might cause truncation if length is miscalculated
    test_package_and_compare("Another string: %s", "Another string: testing", "testing");

    // Test with a string that is exactly the size of a common small buffer (e.g., 4 bytes + null)
    test_package_and_compare("Exact string: %s", "Exact string: four", "four");

    // Test with multiple arguments
    test_package_and_compare("Multiple: %d %s %c", "Multiple: 10 hello X", 10, "hello", 'X');

    // Test with a format string that has no arguments
    test_package_and_compare("No arguments", "No arguments");

    // Test with a format string that has a literal percent sign
    test_package_and_compare("Percent %% sign", "Percent % sign");

    // Test with a string containing special characters
    test_package_and_compare("Special chars: !@#$%%^&*()", "Special chars: !@#$%%^&*()");
}

/*
 * Main test suite setup
 */
ZTEST_SUITE(cbprintf_package, NULL, NULL, NULL, NULL, NULL);

ZTEST(cbprintf_package, test_cbprintf_fsc_package)
{
    test_cbprintf_fsc_package();
}

ZTEST(cbprintf_package, test_cbprintf_must_runtime_package)
{
    test_cbprintf_must_runtime_package();
}

ZTEST(cbprintf_package, test_cbprintf_package)
{
    test_cbprintf_package();
}
